body:
Tried the steps below to repro locally, but upgrade consistently goes through without issues.

#### Download yugabyte releases `2.4.4` and `2.8.3`
```
wget https://downloads.yugabyte.com/releases/2.4.4.0/yugabyte-2.4.4.0-b7-darwin-x86_64.tar.gz
tar xvfz yugabyte-2.4.4.0-b7-darwin-x86_64.tar.gz
wget https://s3.us-west-2.amazonaws.com/downloads.yugabyte.com/releases/2.8.3.0/yugabyte-2.8.3.0-b19-darwin-x86_64.tar.gz
tar xvfz yugabyte-2.8.3.0-b19-darwin-x86_64.tar.gz
```

#### Create a 2.4.4 cluster
In the `2.4.4.0` release folder run:
```
./bin/yb-ctl destroy && ./bin/yb-ctl create --rf 3
./bin/ysqlsh
```

#### Set up database objects
Create user, schemas, databases, tables, indexes, foreign-key constraints, etc.
```
CREATE ROLE test_user WITH LOGIN PASSWORD '1234';
CREATE SCHEMA myschema;

CREATE TABLE myschema.t1(h1 int, r1 text, v1 int unique, v2 text, primary key (h1 HASH, r1 ASC));
CREATE INDEX ON myschema.t1(v2);
INSERT INTO myschema.t1(h1, r1, v1, v2) SELECT g / 100, g % 100, g, (g) % 10 FROM generate_series(1,10000) AS g;

GRANT ALL ON ALL TABLES IN SCHEMA myschema to test_user;

CREATE table t2 (r1 int, v int references myschema.t1(v1), primary key (r1 ASC));
INSERT INTO t2(r1, v) SELECT g, g FROM generate_series(1,10000) AS g;

CREATE VIEW v AS SELECT * FROM myschema.t1 ORDER BY v2;

create database foo with colocated = true;
\c foo

CREATE TABLE t1(h1 int, r1 text, v1 int unique, v2 text, primary key (h1, r1));
CREATE INDEX ON t1(v2);
INSERT INTO t1(h1, r1, v1, v2) SELECT g / 100, g % 100, g, (g) % 10 FROM generate_series(1,10000) AS g;

CREATE TYPE mood AS ENUM ('sad', 'ok', 'happy');
CREATE TABLE t2 (k int, v mood);
INSERT INTO t2 values (1, 'sad'), (2, 'ok'), (3, 'happy'), (4, 'ok');
```
#### Simulate the cluster upgrade
```
./bin/yb-ctl stop
```
Go to `2.8.3.0` release folder
```
./bin/yb-ctl start
./bin/yb-admin --master_addresses 127.0.0.1:7100,127.0.0.2:7100,127.0.0.3:7100 -timeout_ms 600000 upgrade_ysql
```

#### Check the cluster data
```
 ./postgres/bin/ysql_dump -d yugabyte
 ./postgres/bin/ysql_dump -d foo
```

A few more details:
